const upsertChargeCodeServiceCharge = `-- name: UpsertChargeCodeServiceCharge :exec
INSERT INTO charge_code_service_charges (tenant_id, property_id, charge_code_id, service_charge_id, sequence, is_active, created_by)
VALUES ($1, $2, $3, $4, $5, true, $6)
ON CONFLICT (charge_code_id, service_charge_id) DO UPDATE SET sequence = EXCLUDED.sequence, is_active = true
`

type UpsertChargeCodeServiceChargeParams struct {
	TenantID        int64
	PropertyID      int64
	ChargeCodeID    int64
	ServiceChargeID int64
	Sequence        int16
	ActorID         *int64
}

func (q *Queries) UpsertChargeCodeServiceCharge(ctx context.Context, arg UpsertChargeCodeServiceChargeParams) error {
	_, err := q.db.Exec(ctx, upsertChargeCodeServiceCharge,
		arg.TenantID,
		arg.PropertyID,
		arg.ChargeCodeID,
		arg.ServiceChargeID,
		arg.Sequence,
		arg.ActorID,
	)
	return err
}

